import{_ as t,o,c as a,a3 as r}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Reports (Analytics) — Developer Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Reports (Analytics) — Developer Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/analytics"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Reports (Analytics) — Developer Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/analytics"}]]},"headers":[],"relativePath":"developer-guide/analytics.md","filePath":"developer-guide/analytics.md","lastUpdated":1786922765000}'),d={name:"developer-guide/analytics.md"};function s(c,e,i,n,l,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="reports-analytics-—-developer-guide" tabindex="-1">Reports (Analytics) — Developer Guide <a class="header-anchor" href="#reports-analytics-—-developer-guide" aria-label="Permalink to &quot;Reports (Analytics) — Developer Guide&quot;">​</a></h1><p>Slug <code>analytics</code> (display name <strong>Reports</strong>). Free Operations Marketplace module (<strong>1.4.0</strong>). Soft-depends on source modules — <strong>no</strong> hard <code>module_dependencies</code> rows.</p><h2 id="services" tabindex="-1">Services <a class="header-anchor" href="#services" aria-label="Permalink to &quot;Services&quot;">​</a></h2><ul><li><code>AnalyticsOverviewService</code> — executive overview sections</li><li><code>AnalyticsDomainReportService</code> — CRM / Sales / Billing / Purchasing / People reports + shared soft gates</li><li>CSV: <code>App\\Exports\\Analytics\\AnalyticsDomainReportExport</code></li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>analytics.view</code> (overview, domain reports, CSV export).</p><h2 id="soft-sources" tabindex="-1">Soft sources <a class="header-anchor" href="#soft-sources" aria-label="Permalink to &quot;Soft sources&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Modules</th></tr></thead><tbody><tr><td>CRM</td><td><code>leads</code>, <code>tasks</code></td></tr><tr><td>Sales</td><td><code>opportunities</code>, <code>quotations</code>, <code>contracts</code></td></tr><tr><td>Billing</td><td><code>invoices</code>, <code>payments</code>, <code>credit-notes</code></td></tr><tr><td>Purchasing</td><td><code>vendors</code>, <code>purchase-orders</code>, <code>expenses</code></td></tr><tr><td>People</td><td><code>employees</code>, <code>leave-management</code>, <code>attendance</code>, <code>payroll</code></td></tr><tr><td>Overview (extra)</td><td>also <code>help-desk</code>, <code>projects</code></td></tr></tbody></table><p>People leave/attendance aggregates mirror list policies: non-approvers / non-managers see only their linked employee. Employees remain org-wide (<code>EmployeePolicy</code>). Payroll soft-gates on entitlement + <code>payroll.view</code> only (no staff self-scope; staff roles omit <code>payroll.view</code> by default). Soft gate remains entitlement + <code>{module}.view</code>.</p><p>Do <strong>not</strong> merge <a href="/developer-guide/departments">Department reports</a> or <a href="/developer-guide/financial-reports">Financial Reports</a> into Analytics; keep those SKUs/surfaces separate (link from People hub if useful).</p><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><ul><li>Hub <code>/analytics</code> (Overview → Reports) — Recharts per entitled module (pie / donut / bar / area / line by metric)</li><li>Domain pages <code>/analytics/crm|sales|billing|purchasing|people</code> — chart type chosen per source (status mix vs value compare) + table + CSV</li><li>Playwright: <code>npm run test:e2e:analytics</code> / <code>:modules</code> / <code>:authz</code> (+ <code>:headed</code>)</li></ul><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><p>Pest: <code>tests/Feature/Tenant/Analytics/</code> (overview + domain reports + CSV, including People self-scope and Payroll <code>payroll.view</code> gate). Charts are SPA-only (no API change).</p><h2 id="catalog" tabindex="-1">Catalog <a class="header-anchor" href="#catalog" aria-label="Permalink to &quot;Catalog&quot;">​</a></h2><p>Migrate-only bumps: <code>1.0.0</code> → <code>1.1.0</code> (Reports suite) → <code>1.2.0</code> (charts) → <code>1.3.0</code> (People / HR domain) → <code>1.3.1</code> (mixed chart types) → <code>1.4.0</code> (People Payroll soft source). Bump migration filenames must ascend SemVer. Entitlements stay on slug <code>analytics</code>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/developer-guide/financial-reports">Financial Reports</a> — accounting statements (separate SKU)</li><li><a href="/developer-guide/departments">Departments</a> — department performance reports (separate owner/manager surface)</li><li><a href="/architecture/module-dependencies">Module Dependencies</a></li><li><a href="/developer-guide/tenant-settings#timezone-and-scheduled-datetimes">Workspace timezone</a></li></ul>',18)])])}const h=t(d,[["render",s]]);export{u as __pageData,h as default};
